function Provider({children}){
 const [loaded]=useState(()=>{try{const raw=localStorage.getItem('atlas-progress');return {...readStoredProgress(raw),raw}}catch{return {progress:null,blocked:true,raw:null}}});
 const [storageBlocked,setStorageBlocked]=useState(loaded.blocked);
 const [warning,setWarning]=useState(loaded.blocked?(loaded.raw===null?'Le stockage est indisponible : exportez votre progression avant de quitter.':'La sauvegarde est illisible ou d’une version inconnue. Elle est protégée ; vous pouvez exporter sa copie depuis Progression.'):'');
 const [data,setData]=useState(()=>loaded.progress||initial);
 const [dark,setDark]=useState(()=>{try{const t=localStorage.getItem('atlas-theme');return t?t==='dark':matchMedia('(prefers-color-scheme: dark)').matches}catch{return false}});
 const [courseDepth,setCourseDepth]=useState(()=>{try{return localStorage.getItem('atlas-course-depth')==='detailed'?'detailed':'essential'}catch{return 'essential'}});
 useEffect(()=>{try{localStorage.setItem('atlas-course-depth',courseDepth)}catch{}},[courseDepth]);
 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';try{localStorage.setItem('atlas-theme',dark?'dark':'light')}catch{}},[dark]);
 useEffect(()=>{if(storageBlocked)return;try{localStorage.setItem('atlas-progress',JSON.stringify(data))}catch{setWarning('Le stockage du navigateur est indisponible : exportez votre progression avant de quitter.')}},[data,storageBlocked]);
 return <Ctx.Provider value={{data,setData,dark,setDark,courseDepth,setCourseDepth,warning,setWarning,storageBlocked,setStorageBlocked,rawStored:loaded.raw}}>{children}</Ctx.Provider>;
}
const useApp=()=>useContext(Ctx);const themeById=id=>themes.find(t=>t.id===Number(id));
function ScrollManager(){
 const location=useLocation(),navigation=useNavigationType(),positions=useRef(new Map()),current=useRef(location.key);
 useEffect(()=>{const previous=history.scrollRestoration;history.scrollRestoration='manual';const record=()=>positions.current.set(current.current,window.scrollY);window.addEventListener('scroll',record,{passive:true});return()=>{window.removeEventListener('scroll',record);history.scrollRestoration=previous}},[]);
 useLayoutEffect(()=>{current.current=location.key;const top=navigation==='POP'?(positions.current.get(location.key)||0):0;window.scrollTo({top,behavior:'instant'})},[location.key,navigation]);
 return null;
}
function Layout(){const {dark,setDark,warning}=useApp();const [menu,setMenu]=useState(false);const menuButton=useRef(null),menuPanel=useRef(null),closeButton=useRef(null);
 const closeMenu=()=>{setMenu(false);requestAnimationFrame(()=>menuButton.current?.focus())};
 useEffect(()=>{const media=matchMedia('(max-width: 900px)');const changed=event=>{if(!event.matches)setMenu(false)};media.addEventListener('change',changed);return()=>media.removeEventListener('change',changed)},[]);
 useEffect(()=>{if(!menu)return;closeButton.current?.focus();const handle=e=>{if(e.key==='Escape'){e.preventDefault();closeMenu();return}if(e.key!=='Tab')return;const items=[...menuPanel.current.querySelectorAll('a[href],button:not([disabled])')].filter(x=>x.getClientRects().length);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||!menuPanel.current.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!menuPanel.current.contains(document.activeElement))){e.preventDefault();first.focus()}};document.addEventListener('keydown',handle);return()=>document.removeEventListener('keydown',handle)},[menu]);const links=[['/',LayoutDashboard,'Accueil'],['/apprendre',BookOpen,'Apprendre'],['/glossaire',Layers,'Glossaire'],['/flashcards',SquareStack,'Flashcards'],['/quiz',Target,'Quiz'],['/progression',GraduationCap,'Progression']];return <div className="shell"><a href="#contenu-principal" className="skip-link">Aller au contenu principal</a><ScrollManager/><aside id="site-navigation" ref={menuPanel} role={menu?"dialog":undefined} aria-modal={menu?true:undefined} aria-label="Navigation principale" className={'sidebar '+(menu?'opened':'')}><div className="brand"><Link to="/" onClick={closeMenu}><span className="brand-mark">✳</span><span>atlas<span className="brand-accent">.</span><small>IA</small></span></Link><button ref={closeButton} className="mobile-close iconbtn" onClick={closeMenu} aria-label="Fermer le menu"><X size={19}/></button></div><div className="side-label">VOTRE ESPACE</div><nav>{links.map(([path,Icon,label])=><NavLink end={path==='/'} key={path} to={path} onClick={closeMenu} className={({isActive})=>'navlink '+(isActive?'active':'')}><Icon size={18}/>{label}</NavLink>)}</nav><div className="side-bottom"><div className="side-note"><Sparkles size={16}/><p>Une notion à la fois.<br/><strong>À votre rythme.</strong></p></div><button className="theme-toggle" onClick={()=>setDark(!dark)}>{dark?<Sun size={17}/>:<Moon size={17}/>} Mode {dark?'clair':'sombre'}</button></div></aside><div className="mainarea" inert={menu?true:undefined}><header className="topbar"><button ref={menuButton} className="mobile-menu iconbtn" onClick={()=>setMenu(true)} aria-label="Ouvrir le menu" aria-expanded={menu} aria-controls="site-navigation"><Menu/></button><span className="top-context">VOTRE BIBLIOTHÈQUE D’APPRENTISSAGE</span><Link className="top-search" to="/glossaire"><Search size={16}/> <span>Rechercher une notion...</span><kbd>⌕</kbd></Link><div className="top-badge"><span/> EN FRANÇAIS</div></header>{warning&&<div className="warning">{warning}</div>}<main id="contenu-principal" tabIndex={-1}><Suspense fallback={<p className="content" role="status">Chargement de la page…</p>}><Routes><Route path="/" element={<Home/>}/><Route path="/apprendre" element={<LazyLearn/>}/><Route path="/parcours" element={<StarterPath/>}/><Route path="/distinctions" element={<LazyDistinctions/>}/><Route path="/themes/:id" element={<LazyThemePage/>}/><Route path="/cours/:id" element={<LazyCourse/>}/><Route path="/glossaire" element={<LazyGlossary/>}/><Route path="/notions/:id" element={<LazyNotion/>}/><Route path="/flashcards" element={<FlashcardsPage/>}/><Route path="/quiz" element={<LazyQuiz/>}/><Route path="/progression" element={<LazyProgress/>}/><Route path="*" element={<NotFound/>}/></Routes></Suspense><footer><span><b>✳ atlas.IA</b> · Apprendre à voir plus clair.</span><span>Fait pour les curieux · sans compte</span></footer></main></div>{menu&&<button className="overlay" tabIndex={-1} onClick={closeMenu} aria-label="Fermer le menu"/>}</div>}
function ThemeCard({t}){const {data}=useApp();let n=data.completed.filter(x=>x.startsWith(t.id+'-')).length;return <Link className="theme-card" to={'/themes/'+t.id} style={{'--card-color':`var(--c${(t.id-1)%4})`}}><div className="card-head"><span className="card-icon">{icons[t.id-1]}</span><span className="card-num">{moduleNumber(t.id)}</span></div><div className="card-body"><span className="card-kicker">{sourceLabels[t.id-1]}</span><h3>{short[t.id-1]}</h3><p>{descriptions[t.id-1]}</p></div><div className="card-footer"><span>{t.entries.length} notions · {n}/3 leçons</span><ArrowRight size={16}/></div></Link>}
function Home(){const {data}=useApp();const next=resumeLesson(data);return <div className="content"><section className="hero"><div className="hero-copy"><Eyebrow>APPRENDRE L’IA, SIMPLEMENT</Eyebrow><h1>Les grandes idées,<br/><em>à portée de main.</em></h1><p>Des modèles aux agents, explorez l’intelligence artificielle à votre rythme. Une notion, un déclic, puis le suivant.</p><div className="actions">{next?<Btn to={lessonPath(next)} state={{resumePosition:true}}>{data.completed.length||data.lastLesson?'Reprendre mon parcours':'Je débute : commencer la première leçon'}</Btn>:<Btn to="/apprendre">Explorer les thèmes</Btn>}<Btn to="/quiz" secondary>Se tester</Btn></div><p className="home-guidance">Commencez par les fondamentaux, puis avancez à votre rythme. Votre progression reste dans ce navigateur : pensez à <Link to="/progression">l’exporter</Link> pour la conserver.</p><div className="hero-meta"><span><b>{themes.length}</b> thèmes</span><i/><span><b>{entries.length}</b> notions</span><i/><span><b>100 %</b> à votre rythme</span></div></div><div className="hero-art" aria-hidden="true"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="orbit orbit-three"/><div className="art-center"><span>✳</span><small>ATLAS IA</small></div><div className="art-label label-one">TOKENS <b>01</b></div><div className="art-label label-two">ATTENTION <b>02</b></div><div className="art-label label-three">AGENTS <b>03</b></div><div className="art-dot dot-one"/><div className="art-dot dot-two"/><div className="art-dot dot-three"/></div></section><div className="section-title"><div><Eyebrow>UN BON POINT DE DÉPART</Eyebrow><h2>Par où commencer<span className="accent"> ?</span></h2><p>Choisissez un sujet ou suivez le fil, dans l’ordre qui vous plaît.</p></div><Link className="text-link" to="/apprendre">Tous les thèmes <ArrowRight size={16}/></Link></div><div className="theme-grid">{orderedThemes.slice(0,4).map(t=><ThemeCard key={t.id} t={t}/>)}</div><section className="continue-strip"><div className="strip-icon"><GraduationCap size={24}/></div><div><span className="card-kicker">VOTRE PROGRESSION</span><h3>Chaque notion compte.</h3><p>{data.completed.length ? `${data.completed.length} leçon${data.completed.length>1?'s':''} terminée${data.completed.length>1?'s':''}. Continuez comme ça.` : 'Votre progression est enregistrée directement dans ce navigateur.'}</p></div><Link to="/progression" className="text-link">Voir ma progression <ArrowRight size={16}/></Link></section></div>}
