   return <div className="content reading quiz-result"><Eyebrow>SESSION TERMINÉE</Eyebrow><div className="score"><span>VOTRE RÉSULTAT</span><strong>{score}<small> / {s.items.length}</small></strong><p>Chaque réponse est une occasion d’apprendre.</p></div><div className="actions"><button className="button" onClick={()=>{save(null);setConfig(true);scrollToQuestion()}}>Nouveau quiz <ArrowRight size={16}/></button><button className="button secondary" onClick={()=>{const reopened=moveQuizSession({...s,finished:false},0);setAnswer(reopened.drafts?.[reopened.items[0].id]??reopened.answers[reopened.items[0].id]?.value??'');save(reopened);scrollToQuestion()}}>Revoir et modifier mes réponses</button>{s.origin&&<Link className="button secondary" to={lessonPath(s.origin)}>Retourner à la leçon <ArrowRight size={16}/></Link>}<Link className="button secondary" to="/progression">Ma progression <ArrowRight size={16}/></Link></div><h2 className="smaller-title">Résultats par thème</h2><div className="quiz-theme-results">{themeResults.map(x=><div key={x.id}><span>{short[x.id-1]}</span><strong>{x.correct} / {x.total}</strong></div>)}</div><h2 className="smaller-title">Corrections</h2><div className="review-list">{s.items.map((q,i)=><div className="review" key={q.id}><span className={s.answers[q.id]?.correct?'success':'incorrect'}>{s.answers[q.id]?.correct?'✓':'×'}</span><div><span className="review-topic">{short[q.theme-1]}</span><b>{i+1}. {q.prompt}</b><p><strong>Réponse attendue :</strong> {formatCorrectAnswer(q)}</p><p>{q.explanation}</p><StudyMarks data={data} setData={setData} group="questions" id={q.id} label="Repérer cette question"/>{q.concept&&entries.some(e=>e.id===q.concept)&&<Link className="text-link" to={'/notions/'+q.concept}>Revoir la notion <ArrowRight size={14}/></Link>}</div></div>)}</div></div>;
