function Progress({authoredQuestions}){const questions=[...authoredQuestions,...legacyQuestions];const {data,setData,setWarning,storageBlocked,setStorageBlocked,rawStored}=useApp();const [pending,setPending]=useState(null),[error,setError]=useState('');const [lastExport,setLastExport]=useState(()=>{try{return localStorage.getItem('atlas-last-export')||''}catch{return ''}});const download=(value,name)=>{const url=URL.createObjectURL(new Blob([value],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)};const exportData=()=>{download(JSON.stringify(data,null,2),'atlas-ia-progression.json');const now=new Date().toISOString();setLastExport(now);try{localStorage.setItem('atlas-last-export',now)}catch{}};function read(e){const file=e.target.files?.[0];if(!file)return;file.text().then(text=>{try{let p=JSON.parse(text);if(!validateProgress(p))throw Error();const known=new Set(entries.map(x=>x.id));const validCompleted=new Set(themes.flatMap(t=>[1,2,3].map(n=>t.id+'-'+n)));const knownQuestions=new Set(questions.map(q=>q.id));const cleanedFlashcards=cleanFlashcards(p.flashcards,known);const cleanedMarks=cleanStudyMarks(p.studyMarks,knownQuestions,known);const clean={...p,...(cleanedMarks?{studyMarks:cleanedMarks}:{}),...(p.flashcards!==undefined?{flashcards:cleanedFlashcards.value}:{}),favorites:p.favorites.filter(x=>known.has(x)),completed:p.completed.filter(x=>validCompleted.has(x)),errors:p.errors.filter(x=>knownQuestions.has(x)),session:p.session?.items.some(q=>!knownQuestions.has(q.id))?null:p.session};const removed=clean.favorites.length!==p.favorites.length||clean.completed.length!==p.completed.length||clean.errors.length!==p.errors.length||(p.session&&!clean.session)||cleanedFlashcards.removed||(p.studyMarks&&JSON.stringify(cleanedMarks)!==JSON.stringify(p.studyMarks));setPending(clean);setError(removed?'Certaines entrées inconnues ont été ignorées.':'')}catch{setError('Fichier invalide ou version non prise en charge. Votre progression n’a pas été modifiée.');setPending(null)}});e.target.value=''}return <div className="content narrow progress-page"><PageHead eyebrow="VOTRE PARCOURS" title={<>Chaque pas <em>compte.</em></>} description="Retrouvez vos étapes franchies et vos notions enregistrées dans ce navigateur."/><p className="progress-explainer">Une leçon terminée indique votre avancement de lecture ; les quiz et vos propres repères de flashcards donnent des informations complémentaires, sans mesurer à eux seuls la maîtrise.</p><div className="stats-grid"><div><span>LEÇONS TERMINÉES</span><strong>{data.completed.length}<small> / {themes.length*3}</small></strong></div><div><span>NOTIONS FAVORITES</span><strong>{data.favorites.length}</strong></div><div><span>RÉSULTATS CONSERVÉS</span><strong>{data.history.length}</strong></div></div><div className="flashcards-progress-summary"><div><b>Flashcards</b><p>{entries.filter(entry=>data.flashcards?.status?.[entry.id]==='known').length} connues · {entries.filter(entry=>data.flashcards?.status?.[entry.id]==='review').length} à revoir</p></div><Link className="text-link" to="/flashcards">Réviser <ArrowRight size={16}/></Link></div>{resumeLesson(data)&&<div className="resume"><div><b>Votre prochaine étape</b><p>{courseTitles[resumeLesson(data).theme-1][resumeLesson(data).step-1]} · {short[resumeLesson(data).theme-1]}</p></div><div className="actions"><Link className="button secondary" to={lessonPath(resumeLesson(data))} state={{resumePosition:true}}>Reprendre le parcours <ArrowRight size={16}/></Link>{data.lastLesson&&themeById(data.lastLesson.theme)&&<Link className="text-link" to={'/themes/'+data.lastLesson.theme}>Continuer {short[data.lastLesson.theme-1]} <ArrowRight size={16}/></Link>}</div></div>}{data.errors.length>0&&<p className="progress-explainer">{data.errors.length} question(s) à revoir. <Link className="text-link" to="/quiz?scope=errors">Revoir mes erreurs</Link></p>}<section className="review-now"><h2 className="smaller-title">À revoir maintenant</h2><p>{data.errors.length} question(s) à revoir · {dueFlashcardIds(data.flashcards||{status:{}}).length} carte(s) à réviser</p><div className="actions">{data.errors.length>0&&<Link className="text-link" to="/quiz?scope=errors">Revoir mes erreurs</Link>}<Link className="text-link" to="/flashcards?scope=due">Réviser mes cartes</Link></div></section><h2 className="smaller-title">Progression par thème</h2><div className="progress-list">{orderedThemes.map(t=>{let n=data.completed.filter(x=>x.startsWith(t.id+'-')).length;return <Link to={'/themes/'+t.id} key={t.id}><span>{short[t.id-1]}</span><div className="progress-track"><div style={{width:(n/3*100)+'%'}}/></div><small>{n}/3</small></Link>})}</div><h2 className="smaller-title">Mes repères à revoir ou approfondir</h2>{Object.keys(data.studyMarks?.questions||{}).length>0&&<Link className="text-link" to="/quiz?scope=marked">Refaire mes questions repérées <ArrowRight size={16}/></Link>}<div className="tag-list">{Object.entries(data.studyMarks?.concepts||{}).map(([id,mark])=>{const entry=entriesById.get(id);return entry&&<Link key={id} className="tag" to={'/notions/'+id}>{conceptName(entry)} · {mark==='review'?'À revoir':'À approfondir'}</Link>})}</div><div className="review-list">{Object.entries(data.studyMarks?.questions||{}).map(([id,mark])=>{const q=questions.find(item=>item.id===id);return q&&<details key={id} className="review"><summary>{mark==='review'?'À revoir':'À approfondir'} · {q.prompt}</summary><p><b>Réponse attendue :</b> {formatCorrectAnswer(q)}</p><p>{q.explanation}</p>{q.concept&&<Link className="text-link" to={'/notions/'+q.concept}>Revoir la notion</Link>}<StudyMarks data={data} setData={setData} group="questions" id={id} label="Repérer cette question"/></details>})}{!Object.keys(data.studyMarks?.concepts||{}).length&&!Object.keys(data.studyMarks?.questions||{}).length&&<p className="muted">Repérez une question ou une notion pendant vos révisions pour la retrouver ici.</p>}</div><h2 className="smaller-title">Mes favoris</h2><div className="tag-list">{data.favorites.length?data.favorites.map(id=>{let e=entries.find(x=>x.id===id);return e&&<Link className="tag" key={id} to={'/notions/'+id}>{conceptName(e)} <ChevronRight size={14}/></Link>}):<p className="muted">Enregistrez des notions depuis leurs fiches pour les retrouver ici.</p>}</div><h2 className="smaller-title">Derniers quiz</h2>{data.history.length?<div className="lesson-list">{data.history.map(h=><div key={h.id} className="lesson-row"><span className="lesson-name"><b>{h.correct} / {h.total} bonnes réponses</b><small>{new Date(h.date).toLocaleDateString('fr-FR')} · {h.origin?courseTitles[h.origin.theme-1]?.[h.origin.step-1]||'Leçon':Array.isArray(h.themes)?h.themes.map(t=>short[t-1]).filter(Boolean).join(', '):'Thème non enregistré'}{h.mode?` · ${h.mode==='exam'?'Évaluation':'Apprentissage'}`:''}{h.level&&h.level!=='all'?` · ${h.level}`:''}</small>{Array.isArray(h.results)&&<details><summary>Voir les corrections</summary>{h.results.map(result=>{const q=questions.find(item=>item.id===result.id);return q?<p key={result.id}>{result.correct?'✓':'✗'} {q.prompt}<br/>Réponse attendue : {formatCorrectAnswer(q)}<br/>{q.explanation}</p>:null})}</details>}</span><CheckCircle2 size={18}/></div>)}</div>:<p className="muted">Aucun quiz terminé pour le moment.</p>}<div className="backup"><div><h3>Emporter ma progression</h3><p>Exportez un fichier pour garder une copie ou le transférer sur un autre appareil. Pour le restaurer, ouvrez cette page sur l’autre appareil puis choisissez Importer.</p><p>{lastExport?`Dernier export sur cet appareil : ${new Date(lastExport).toLocaleDateString('fr-FR')}.`:data.completed.length>=3?'Pensez à exporter une copie de votre progression.':'Aucun export enregistré sur cet appareil.'}</p></div><div className="actions"><button className="button secondary" onClick={exportData}><Download size={16}/> Exporter</button>{storageBlocked&&rawStored!==null&&<button className="button secondary" onClick={()=>download(rawStored,'atlas-ia-sauvegarde-originale.json')}><Download size={16}/> Exporter la sauvegarde originale</button>}<label className="button secondary file-button"><Upload size={16}/> Importer<input type="file" accept="application/json,.json" onChange={read}/></label></div>{error&&<p className="incorrect">{error}</p>}{pending&&<div className="import-preview"><b>Sauvegarde valide : {pending.completed.length} leçons, {pending.favorites.length} favoris, {pending.history.length} résultats{pending.flashcards?`, ${Object.keys(pending.flashcards.status).length} notions de flashcards`:''}.</b><p>La progression actuelle sera remplacée.</p><button className="button" onClick={()=>{setData(pending);setStorageBlocked(false);setPending(null);setWarning('Progression importée.')}}>Confirmer le remplacement</button> <button className="button secondary" onClick={()=>setPending(null)}>Annuler</button></div>}</div></div>}
function NotFound(){return <div className="content narrow"><PageHead eyebrow="PAGE INTROUVABLE" title="Oups, ce chemin n’existe pas." description="Revenez à l’accueil pour reprendre votre exploration."/><Btn to="/">Retour à l’accueil</Btn></div>}
const withCurriculum=Component=>lazy(()=>Promise.all([import('./courseCurriculum.js'),import('./notionLearningLinks.js'),import('./priorityContent.js'),import('./distinctions.json')]).then(([{courseEditorial},{getNotionLearningLinks},{priorityContent},{default:distinctions}])=>({default:()=> <Component courseEditorial={courseEditorial} getNotionLearningLinks={getNotionLearningLinks} priorityContent={priorityContent} distinctions={distinctions}/>})));
const withDistinctions=Component=>lazy(()=>import('./distinctions.json').then(({default:distinctions})=>({default:()=> <Component distinctions={distinctions}/>})));
const LazyLearn=withDistinctions(Learn),LazyDistinctions=withDistinctions(Distinctions);
const LazyThemePage=withCurriculum(ThemePage),LazyCourse=withCurriculum(Course),LazyNotion=withCurriculum(Notion);
const loadQuestions=()=>Promise.all([import('./allQuestions.js'),import('./additionalQuestions.js')]).then(([base,extra])=>[...base.authoredQuestions,...extra.additionalQuestions]);
const withQuestions=Component=>lazy(()=>loadQuestions().then(authoredQuestions=>({default:()=> <Component authoredQuestions={authoredQuestions}/>})));
const LazyGlossary=withQuestions(Glossary),LazyProgress=withQuestions(Progress);
const LazyQuiz=lazy(()=>Promise.all([loadQuestions(),import('./courseCurriculum.js')]).then(([authoredQuestions,{courseEditorial}])=>({default:()=> <Quiz authoredQuestions={authoredQuestions} courseEditorial={courseEditorial}/>})));

createRoot(document.getElementById('root')).render(<BrowserRouter basename={import.meta.env.BASE_URL}><Provider><ErrorBoundary><Layout/></ErrorBoundary></Provider></BrowserRouter>);
